budget.value:
fun p =>
  have B := max 1 ⌈256 * p.σ ^ 2 / p.ε⌉₊;
  have t := DistributedTemplate.clockBits + B.size;
  have w := 32 + 4 * (2 + p.d + ⌈2 * p.L * p.Δ / p.ε⌉₊ + ⌈p.σ ^ 2 / p.ε⌉₊).log2;
  have α := fun S => ⨅ C, ∑ e, if (↑e).1 ∈ ↑C ↔ (↑e).2 ∈ ↑C then 0 else p.b (↑e).1 (↑e).2;
  have m := Fintype.card (LongTails.Algorithms.GraceGraph.Link p);
  have P := 16 * ↑(p.d * (w + t) + t * (m + 1) * ↑p.n);
  ↑(⌈32 * p.L * p.Δ / p.ε⌉₊ - 1) * ⨅ S, ↑(B + (↑S).card) / ∑ i ∈ ↑S, (p.h i)⁻¹ + if (↑S).card ≤ 1 then 0 else P / α ↑S

